<?php foreach($visibleKinds as $kind):$files=array_values(array_filter($detail['assets'],fn($a)=>$a['kind']===$kind));?><details class="panel" <?=$files?'open':''?>><summary><?=e($kinds[$kind])?> · <?=count($files)?></summary><?php if(!$files):?><p class="muted">Пока нет файлов.</p><?php else:?><div class="photos"><?php foreach($files as $file):?><a target="_blank" rel="noopener" href="?asset=<?=e($file['id'])?>"><?php if(str_starts_with($file['mime'],'image/')):?><img loading="lazy" src="?asset=<?=e($file['id'])?>" alt=""><?php endif;?><b><?=e($file['name'])?></b><br><small><?=round($file['bytes']/1048576,2)?> МБ · <?=e(erpDate($file['created_at']))?></small></a><?php endforeach;?></div><?php endif;?></details><?php endforeach;?>
